3	/**
4	 * el.outerHTML is not polyfilled so we need to recreate the tag + attributes and
5	 * combine it with el.innerHTML.
6	 *
7	 * @param {Element} el Element you want to get the out Html from
8	 * @returns {String} outer html
9	 */
10	export const getOuterHtml = el => {
11	  /* istanbul ignore next */
12	  if (window.ShadyCSS && window.ShadyCSS.nativeShadow === false) {
13	    const tagName = el.tagName.toLowerCase();
14	    let attributes = ' ';
15	    Array.prototype.slice.call(el.attributes).forEach(item => {
16	      attributes += `${item.name}="${item.value}" `;
17	    });
18	    // removes last ' ' or if there are no attributes makes it to equal ''
19	    attributes = attributes.slice(0, -1);
20	    return `<${tagName}${attributes}>${el.innerHTML}</${tagName}>`;
21	  }
22	  return el.outerHTML;
23	};
24	
25	/**
26	 * For comparison we do not need the style scoping classes on polyfilled browsers
27	 * Rather naive approach for now - probably need to improve once we have failing cases.
28	 *
29	 * @param {Element} el Element you want to get the cleaned shadow dom
30	 * @returns {String} cleaned shadow dom
31	 */
32	export const getCleanedShadowDom = el => {
33	  /* istanbul ignore next */
34	  if (window.ShadyCSS && window.ShadyCSS.nativeShadow === false) {
35	    const tagName = el.tagName.toLowerCase();
36	    const regexTagName = new RegExp(tagName, 'g');
37	    let domString = el.shadowRoot.innerHTML;
38	    domString = domString.replace(/style-scope/g, ''); // remove style-scope class
39	    domString = domString.replace(regexTagName, ''); // remove scoped class name
40	    domString = domString.replace(/(class=".*?)(\s)*"/g, '$1"'); // remove trailing spaces in class=" "
41	    domString = domString.replace(/ class="\w?"/g, ''); // remove empty class attributes
42	    return domString;
43	  }
44	  return el.shadowRoot.innerHTML;
45	};
46	
47	export function snapshotPath(rootNode) {
48	  const path = [];
49	  let node = rootNode;
50	
51	  while (node && node.parent) {
52	    path.push(node.title);
53	    node = node.parent;
54	  }
55	  return path.reverse();
56	}
